PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE media (`url` TEXT, `originalUrl` TEXT, `thumbnailUrl` TEXT, `mediaID` INTEGER PRIMARY KEY, `occid` INTEGER);
CREATE TABLE omoccurrences (`occid` INTEGER PRIMARY KEY, `catalogNumber` TEXT, `otherCatalogNumbers` TEXT, `family` TEXT, `genus` TEXT, `scientificName` TEXT, `sciname` TEXT, `continent` TEXT, `country` TEXT, `stateProvince` TEXT, `county` TEXT, `municipality` TEXT, `locality` TEXT, `decimalLatitude` REAL, `decimalLongitude` REAL, `collid` INTEGER, `tidInterpreted` INTEGER, `eventDate` TEXT, `dateLastModified` TEXT);
CREATE TABLE omcollections (`collectionName` TEXT, `collectionCode` TEXT, `institutionCode` TEXT, `collID` INTEGER PRIMARY KEY);
CREATE TABLE taxa (`sciName` TEXT, `tid` INTEGER PRIMARY KEY);
CREATE TABLE taxstatus (`tid` INTEGER, `family` TEXT, `parenttid` INTEGER);
CREATE INDEX idx_media_occid ON media(occid);
CREATE INDEX idx_omoccurrences_collid ON omoccurrences(collid);
CREATE INDEX idx_omoccurrences_tidInterpreted ON omoccurrences(tidInterpreted);
CREATE INDEX idx_taxstatus_tid ON taxstatus(tid);
CREATE INDEX idx_taxstatus_parenttid ON taxstatus(parenttid);
COMMIT;
